def transform(g):
    H,W=len(g),len(g[0])
    threes={(r,c) for r in range(H) for c in range(W) if g[r][c]==3}
    seen=set(); shapes=[]  # (cr,cc,col,arms)
    for (r,c) in sorted(threes):
        if (r,c) in seen: continue
        done=False
        for dr in (0,1):
            for dc in (0,1):
                cr,cc=r+dr,c+dc
                arms=[(cr-1,cc),(cr+1,cc),(cr,cc-1),(cr,cc+1)]
                if all(a in threes for a in arms) and g[cr][cc]!=3:
                    shapes.append((cr,cc,g[cr][cc],set(arms))); seen.update(arms); done=True; break
            if done: break
    o=[[0]*W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            if g[r][c]==3: o[r][c]=3
    def paint(cr,cc,col,arms,horizontal):
        for dr,dc in ([0,-1],[0,1]) if horizontal else ([-1,0],[1,0]):
            r,c=cr,cc
            while True:
                r,c=r+dr,c+dc
                if not(0<=r<H and 0<=c<W): break
                if (r,c) in arms: continue          # own arm: keep 3, pass through
                if (r,c) in threes: break           # other shape's 3: block
                o[r][c]=col
    for cr,cc,col,arms in shapes: paint(cr,cc,col,arms,True)
    for cr,cc,col,arms in shapes: paint(cr,cc,col,arms,False)
    return o
